entries[459805] = { ["name"] = "Wailing Arrow", ["text"] = "Instant\nAfter summoning 20 Wind Arrows, your next Aimed Shot becomes a Wailing Arrow.\n\nWailing Arrow\nFire an enchanted arrow, dealing (360% of Attack Power) Shadow damage to your target and an additional (112.5% of Attack Power) Shadow damage to all enemies within 8 yds of your target. Non-Player targets struck by a Wailing Arrow have their spellcasting interrupted and are silenced for 3 sec. [ Readiness : Wailing Arrow resets the cooldown of Rapid Fire and generates 2 charges of Aimed Shot ] [ Windrunner's Barrage : Wailing Arrow fires off 5 Wind Arrows at your primary target, and 10 Wind Arrows split among any secondary targets hit, each dealing (20% of Attack Power) Physical damage ]" }
entries[459806] = { ["name"] = "Wailing Arrow", ["text"] = "After summoning 20 Wind Arrows, your next Aimed Shot becomes a Wailing Arrow.\n\nWailing Arrow\nFire an enchanted arrow, dealing (360% of Attack Power) Shadow damage to your target and an additional (112.5% of Attack Power) Shadow damage to all enemies within 8 yds of your target. Non-Player targets struck by a Wailing Arrow have their spellcasting interrupted and are silenced for 3 sec. [ Readiness : Wailing Arrow resets the cooldown of Rapid Fire and generates 2 charges of Aimed Shot ] [ Windrunner's Barrage : Wailing Arrow fires off 5 Wind Arrows at your primary target, and 10 Wind Arrows split among any secondary targets hit, each dealing (20% of Attack Power) Physical damage ]" }
entries[459808] = { ["name"] = "Wailing Arrow", ["text"] = "Instant\nSummoning a Dire Beast 6 times sounds the Horn of Valor, summoning either Hati or Fenryr to battle.\n\nHati\nIncreases the damage of all your pets by 4%.\n\nFenryr\nPounces your primary target, inflicting a heavy bleed that deals (1600% of Attack Power) damage over 8 sec and grants you 4% Haste." }
